from h import *
R(9412428,"سالسا المانجو والهابانيرو",
"سالسا المانجو والهابانيرو هي المزيج المثالي بين الحلو والحار. لذيذة ومن الصعب التوقف عنها بـ 7 مكونات فقط!",
"6 حصص","حصة واحدة",
["1¾ كوب مانجو مقطعة مكعبات من حوالي حبة مانجو كبيرة ناضجة","1½ كوب طماطم مقطعة مكعبات من حوالي حبتي طماطم روما","½ كوب بصل أحمر مقطع مكعبات","1 حبة فلفل هابانيرو مفرومة ناعمًا جدًا","½ كوب كزبرة خضراء طازجة مفرومة (غير مكبوسة، مع إزالة السيقان السميكة)","2 ملعقة كبيرة عصير ليمون أخضر، أي حوالي ليمونة خضراء كبيرة","½ ملعقة صغيرة ملح البحر أو حسب الرغبة"],
["إذا كان لديك محضّر طعام صغير، فأنصح بشدة باستخدامه لفرم فلفل الهابانيرو ناعمًا. فهذا يقلل لمس الفلفل بيديك. انزع الساق وقطّع الفلفل إلى نصفين. ثم اخلطه في المحضّر.","إذا لم يكن لديك محضّر صغير، فيمكنك التقطيع يدويًا. ومع ذلك، أنصح بارتداء قفازات عند التعامل مع الفلفل الحار، إن أمكن. احرص على غسل يديك جيدًا بعد التقطيع.","ضع جميع المكونات المقطعة وعصير الليمون الأخضر والملح في وعاء متوسط وقلّب جيدًا لتوزيع النكهات بالتساوي. قدّمها فورًا، أو ضعها في الثلاجة لمدة ساعة لتبرد."],
["إذا كنت تستخدم مانجو مجمدة، فتأكد من إذابتها تمامًا أولًا. لتقليل الحرارة، أزل بذور فلفل الهابانيرو أو استخدم فلفل الهالبينو بدلًا منه. ارتدِ قفازات عند التعامل مع الفلفل الحار، إن أمكن، واغسل يديك جيدًا عند الانتهاء. تجنب لمس وجهك. وإذا لم يكن لديك قفازات، فجرّب استخدام قطعة من الغلاف البلاستيكي حول يديك."])
R(9413497,"ريزوتو الأرز البني بالخضار في Instant Pot",
"ريزوتو أرز بني حالم في Instant Pot ستحبه أنت وعائلتك!",
"6 حصص","حصة واحدة",
["1½ كوب أرز بسمتي بني مشطوف","4 أكواب خضار مجمدة مشكلة، أستخدم خليط الذرة/البازلاء/الجزر/الفاصولياء الخضراء","4 أكواب مرق خضار قليل الصوديوم","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة أوريجانو مجفف","1 ملعقة كبيرة زبدة نباتية أو سمن نباتي (مارجرين)، اختياري","ملح + فلفل حسب الرغبة","بقدونس طازج","جبن بارميزان نباتي"],
["ضع كل شيء ما عدا الزبدة في قدر الطهي بالضغط وقلّب. أغلق الغطاء وتأكد من أن الصمام في وضع الإغلاق. ثم اضبطه على ضغط عالٍ لمدة 22 دقيقة. سيستغرق وصول القدر إلى الضغط حوالي 15-20 دقيقة.","عند انتهاء المؤقت، اترك قدر الطهي بالضغط يُطلق الضغط طبيعيًا لمدة 10 دقائق. وبعد 10 دقائق، أطلق الضغط المتبقي بسرعة بضبط الصمام على وضع التنفيس، وافتح الغطاء عندما يكون ذلك آمنًا.","أضف الزبدة إن استخدمتها وقلّب وتذوّق وأضف الملح والفلفل عند الحاجة. قدّمه مزينًا بالبقدونس الطازج و/أو جبن البارميزان."],
["امنح نفسك وقتًا كافيًا. فرغم أن وقت الطهي مضبوط على 22 دقيقة، سيستغرق وصول القدر إلى الضغط 15-20 دقيقة إضافية، ثم 10 دقائق من الإطلاق الطبيعي للضغط. يبقى المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام. أعد تسخينه على الموقد، أو استخدم وظيفة التقليب (Sauté) في Instant Pot."],
{"Garnishes (optional)":"للتزيين (اختياري)"})
R(9416487,"جبن كريمي نباتي من التوفو [خالٍ من الزيت]",
"جبن كريمي نباتي من التوفو كثيف وكريمي، مثالي للدهن والغمس. إنه مالح وغني بالنكهة ولذيذ.",
"20 حصة (2 ملعقة كبيرة لكل حصة)","2 ملعقة كبيرة",
["16 أونصة توفو متماسك، يُفضَّل أن يكون خاليًا من المحاصيل المعدلة وراثيًا إن أمكن","¼ كوب كاجو نيء أو لوز مقشّر أو بذور دوار الشمس","2 ملعقة كبيرة معجون الميسو","1½ ملعقة كبيرة عصير ليمون","1½ ملعقة كبيرة خل التفاح","¼ ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة شبت"],
["ضع كل شيء في وعاء محضّر الطعام واخلطه حتى يصبح ناعمًا، مع كشط الجوانب عند الحاجة.","ضعه في الثلاجة لمدة ساعة أو أكثر ليبرد ويتكاثف."],
["احرص على تصفية التوفو وتجفيفه بالتربيت لتجنب السائل الزائد في الجبن الكريمي من التوفو. فأنت تريد معجونًا سميكًا يشبه الجبن الحقيقي فعلًا. استخدم محضّر الطعام بدلًا من الخلاط. فسيكون من الأصعب الحصول على خليط ناعم في الخلاط بسبب قلة المكونات السائلة. بالإضافة إلى أنه من الأصعب إخراج المعاجين السميكة من الخلاط، حيث تكون المساحة بين الشفرات أقل. ضعه في الثلاجة لمدة ساعة على الأقل قبل الاستخدام. فهذا يساعده على التماسك والتكاثف. التخزين: احفظ الجبن الكريمي من التوفو في الثلاجة في وعاء محكم الإغلاق أو برطمان زجاجي لمدة 5-7 أيام.","لحفظه لفترة أطول، قسّمه إلى حصص أصغر وجمّد كلها ما عدا واحدة في أوعية محكمة الإغلاق مناسبة للتجميد لمدة تصل إلى 3 أشهر. احتفظ بواحدة في الثلاجة للاستخدام الفوري. وأذِب الحصص المتبقية عند الحاجة."],
{"Optional Flavours":"نكهات اختيارية"})
R(9419746,"رقائق الشمندر بقلاية الهواء [خالية من الزيت]",
"رقائق شمندر مقرمشة ولذيذة بقلاية الهواء بقرمشة مرضية!",
"حصتان","حصة واحدة",
["½ رطل شمندر أحمر، أي حوالي حبتي شمندر متوسطتين","½ ملعقة كبيرة أكوافابا، اختيارية","¼ ملعقة صغيرة ملح البحر"],
["افرك الشمندر واقطع أطرافه بسكين حادة. لا حاجة إلى تقشيره. ثم استخدم المقطّعة (الماندولين) لتقطيع الشمندر إلى رقائق رقيقة جدًا. أنت تريدها رقيقة كالورق للحصول على أفضل النتائج.","ضع شرائح الشمندر في وعاء خلط وقلّبها مع الأكوافابا والملح. ثم رتّبها في طبقة واحدة (لا بأس إذا تراكبت قليلًا) في سلة القلاية بالهواء، مع العمل على دفعات إذا لزم الأمر.","اقلِ رقائق الشمندر بالهواء الساخن على 350° فهرنهايت (175° مئوية) لمدة 10-12 دقيقة، مع رج السلة أو التقليب عند منتصف المدة. تكون الرقائق جاهزة عندما تلتف إلى الأعلى وتنكمش بشكل ملحوظ وتبدو جافة عند اللمس. أخرجها من السلة واتركها في درجة حرارة الغرفة. وستزداد قرمشة عندما تبرد."],
["يمكن أن تتراكب شرائح الشمندر قليلًا لأنها ستنكمش بشكل ملحوظ، لكن لا تكدّسها ولا تجعلها تتراكب كثيرًا وإلا لن تصبح مقرمشة بالقدر نفسه. سمك رقائق الشمندر أو رقتها هو الذي يحدد وقت الطهي ومستوى القرمشة. قطّع الشمندر إلى شرائح رقيقة قدر الإمكان، أو استخدم أداة مثل المقطّعة (الماندولين) لتسهيل التقطيع. تكون الرقائق جاهزة عندما تلتف حوافها وتبدو الشرائح جافة عند اللمس. لا تُفرط في طهي رقائق الشمندر وإلا أصبح طعمها مرًّا. ستزداد قرمشة قليلًا بعد إخراج السلة من قلاية الهواء وترك الرقائق لتبرد."])
R(9419806,"كوكيز الشمندر [كوكيز ريد فيلفت النباتي]",
"كوكيز الشمندر اللذيذ هذا هو لمسة صحية على كوكيز ريد فيلفت. إنه طري ومطاطي وملوّن طبيعيًا بالشمندر الترابي الحلو بدلًا من الملوّن الغذائي.",
"22 قطعة كوكيز","حصة واحدة",
["1½ كوب شمندر مقطع مكعبات، استخدمت علبة 400 مل","⅓ كوب سكر قصب","2 ملعقة صغيرة مستخلص الفانيليا الطبيعي","1 ملعقة صغيرة خل التفاح","150 جرامًا من دقيق الشوفان، أي حوالي 1½ كوب","3 ملاعق كبيرة مسحوق الكاكاو الخام غير المحلى","2 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصوديوم","½ كوب رقائق الشوكولاتة البيضاء النباتية"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن صينية خبز كبيرة بورق الزبدة.","ضع المكونات السائلة في الخلاط واخلطها حتى تصبح ناعمة. ثم اسكبها في وعاء خلط.","أضف المكونات الجافة إلى الوعاء نفسه وقلّب حتى تمتزج. ثم أضف رقائق الشوكولاتة بالتحريك الرفيع من الأسفل إلى الأعلى، إن استخدمتها.","استخدم مغرفة كوكيز لوضع العجين على الصينية المبطّنة بورق الزبدة، مع ترك مسافة بين كل قطعة كوكيز وأخرى لتنتشر.","اخبز كوكيز الشمندر لمدة 10-12 دقيقة، حتى يصبح متماسكًا قليلًا عند اللمس. ثم أخرجه من الفرن واتركه ليبرد لمدة 10 دقائق قبل لمسه."],
["زِن الدقيق للحصول على أدق النتائج. إذا لم يكن لديك ميزان مطبخ، فاسكب الدقيق بالملعقة في كوب القياس واستخدم سكينًا لكشط الزائد، وستحصل على نتائج مماثلة. لا تغترفه من الكيس!","إذا كنت تستخدم شمندرًا معلبًا، فتأكد من أنه ليس مخللًا! استخدم الشمندر المعلب في الماء فقط، بدون خل أو زيت، لأن ذلك سيغيّر النكهة.","استخدم بيكنج باودر طازجًا وفعّالًا. فالبيكنج باودر المفتوح في الخزانة لأكثر من 6 أشهر قد يفقد فعاليته.","اترك الكوكيز يبرد في الصينية لمدة 10 دقائق على الأقل قبل لمسه. فهو هش ويحتاج إلى وقت ليتماسك قبل نقله إلى رف سلكي.","يبقى المتبقي صالحًا في درجة حرارة الغرفة لمدة 1-2 يوم، وفي الثلاجة لمدة تصل إلى 5 أيام، أو مجمدًا لمدة تصل إلى 3 أشهر."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","Optional":"اختياري"})
R(9421240,"بطاطس منزلية بقلاية الهواء [خيار خالٍ من الزيت]",
"البطاطس المنزلية المقرمشة واللذيذة بقلاية الهواء هي طعام الراحة في أفضل حالاته. أكثر صحة من المقلي بالغمر، مع خيار خالٍ من الزيت!",
"3 حصص","حصة واحدة",
["1 رطل بطاطس صفراء مقشّرة ومقطعة إلى قطع بحجم نصف بوصة","⅓ كوب بصل أصفر مقطع مكعبات سميكة (حوالي نصف حبة بصل صغيرة)","½ كوب فلفل أحمر مقطع مكعبات سميكة (حوالي نصف حبة فلفل متوسطة)","¾ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة بابريكا","½ ملعقة صغيرة مسحوق الثوم","2 ملعقة كبيرة زيت أفوكادو أو زيت طهي آخر، اختياري","ثوم معمر (شيف) أو بقدونس أو مزيد من الملح عند الحاجة"],
["قشّر البطاطس وقطّعها إلى قطع بحجم نصف بوصة تقريبًا وضعها في وعاء كبير. غطِّها بالماء البارد واتركها تنقع لمدة 20 دقيقة. ثم صفّها واشطفها بالماء البارد وضعها على منشفة مطبخ نظيفة وجافة وجفّفها بالتربيت. امسح الوعاء حتى يجف وأعد البطاطس إليه.","الآن أضف جميع المكونات المتبقية إلى الوعاء نفسه وقلّب جيدًا لتتغطى بالتساوي.","ضعها في السلة واقلِها بالهواء الساخن على 400° فهرنهايت (200° مئوية) لمدة 15-20 دقيقة، حتى تنضج تمامًا وتصل إلى درجة القرمشة المطلوبة. رجّ السلة أو قلّب البطاطس كل 5 دقائق لينضج بالتساوي."],
["للحصول على أفضل النتائج، خصص وقتًا لنقع البطاطس وشطفها قبل الطهي. فهذا سيعطيك أكثر بطاطس منزلية قرمشة بقلاية الهواء. قطّع البطاطس بحجم متساوٍ قدر الإمكان ليستوي الطهي بالتساوي. تناسب المكعبات بحجم نصف بوصة الطهي السريع وستصبح مقرمشة بشكل جيد. لا تقطّع البصل والفلفل إلى قطع صغيرة جدًا وإلا احترقت وقد تسقط من ثقوب السلة. وإذا لم ترغب في قطع كبيرة، فأضفها فقط عندما تنضج البطاطس إلى النصف تقريبًا. تتفاوت قوة قلايات الهواء، لذا تفقّد البطاطس دائمًا أثناء الطهي. أستخدم Ninja Foodi بسعة 8 كوارت وتكون بطاطسي مثالية عند 20 دقيقة. وقد تنضج النماذج الأصغر أسرع. جرّب التتبيل لإضافة نكهة. جعلتها بسيطة، لكن إذا أردت تغيير النكهات، فيمكنك استبدال البابريكا بالبابريكا المدخنة، و/أو إضافة مسحوق البصل أو مسحوق الفلفل الحار أو الكمون أو الفلفل الحار (كايين). طعمها أفضل وهي طازجة، لكن يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق. أعد تسخينه في سلة القلاية بالهواء أو في فرن التحميص الصغير."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9421474,"معجون الشوكولاتة بالحمص [نوتيلا خالية من المكسرات]",
"معجون شوكولاتة بالحمص (المعروف أيضًا بنوتيلا خالية من المكسرات) كريمي وغني بالشوكولاتة ولذيذ.",
"12 حصة (حوالي 2 ملعقة كبيرة لكل حصة/المجموع حوالي 1½ كوب)","حصة واحدة",
["علبة حمص 15 أونصة مصفّاة + مشطوفة","3 ملاعق كبيرة مسحوق الكاكاو الخام غير المحلى","4 ملاعق كبيرة شراب القيقب","2 ملعقة صغيرة مستخلص الفانيليا الطبيعي","¼ ملعقة صغيرة ملح البحر","1-2 ملعقة كبيرة ماء إن أردت قوامًا أخف"],
["ضع كل شيء ما عدا الماء في وعاء محضّر الطعام واخلطه حتى يمتزج. توقف لكشط جوانب الوعاء عند الحاجة وواصل الخلط حتى يصبح ناعمًا.","إذا أردت قوامًا أخف، فأضف 1-2 ملعقة كبيرة من الماء.","انقل النوتيلا الخالية من المكسرات إلى برطمان زجاجي نظيف وجاف أو وعاء محكم الإغلاق."],
["لا تنسَ كشط جوانب وعاء محضّر الطعام أثناء الخلط. فهذا يضمن قوامًا ناعمًا. أضف ملعقة كبيرة من الماء في كل مرة عند الحاجة للقوام و/أو لقوام أخف.","احفظ معجون الشوكولاتة بالحمص في وعاء زجاجي أو برطمان محكم الإغلاق في الثلاجة لمدة تصل إلى أسبوع. أو جمّده لمدة تصل إلى 3 أشهر."])
R(9422406,"سموذي بدون موز",
"إليك وصفة سموذي لذيذة بدون موز مليئة بالتوت والبروتين. إنها لذيذة ويمكن تعديلها بسهولة حسب ذوقك، وهي مفيدة بنسبة 100%.",
"حصتان (تعطي حوالي 4 أكواب)","حصة واحدة",
["1¼ كوب حليب الكاجو غير المحلى أو حليب نباتي من اختيارك","1 كوب توت أزرق مجمد","1 كوب فراولة مجمدة","1 كوب أناناس مجمد","⅓ كوب بيكان أو جوز أو لوز","2 ملعقة كبيرة عصير ليمون أخضر معصور طازجًا، أي حوالي ليمونة خضراء صغيرة","1 ملعقة كبيرة قلوب بذور القنب، اختيارية"],
["ضع جميع المكونات في الخلاط واخلطها على سرعة عالية حتى تصبح ناعمة. بالهناء والعافية!"],
["خلط الفاكهة المجمدة يعطي أفضل نتيجة مع خلاط عالي السرعة. إذا لم يكن لديك خلاط عالي السرعة، فقد تحتاج إلى القليل من السائل الإضافي ليبدأ الخلط. ابدأ بالكمية المذكورة وأضف المزيد عند الحاجة. وإذا كنت تستبدل أي فاكهة مجمدة بفاكهة طازجة، فقلّل السائل قليلًا في البداية وأضف المزيد إذا لزم الأمر. أضف حفنة من مكعبات الثلج إذا كنت تستخدم فاكهة طازجة في الغالب. فالسموذي بدون موز لن يكون سميكًا تمامًا إذا اعتمدت على خيارات الفاكهة الطازجة فقط. لا تتردد في استبدال أي من الفواكه المجمدة بما يناسب فريزرك. المانجو أو التوت الأحمر (الراسبيري) أو الكرز أو التوت المشكل كلها تناسب. وإذا لم يكن لديك بيكان، فيمكنك استخدام الجوز أو الكاجو أو اللوز أو المكاديميا بدلًا منه. ويمكنك أيضًا استبدال المكسرات النيئة بزبدة المكسرات. جرّب 2 ملعقة كبيرة من زبدة الفول السوداني أو زبدة اللوز أو زبدة البيكان أو أي زبدة مكسرات تفضلها. لمزيد من الحلاوة، أضف 2-3 حبات تمر منزوعة النوى أو 1-2 ملعقة صغيرة من شراب القيقب."])
